const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};

const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  message.caption ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseRange(text) {
  const match = String(text || '').match(/\b([A-Z]{1,3}\d+:[A-Z]{1,3}\d+|[A-Z]{1,3}\d+)\b/i);
  return match ? match[1].toUpperCase() : '';
}

function parseSheetTab(rawText) {
  const text = String(rawText || '').trim();
  const match = text.match(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?([^"'“”‘’]+?)["'“”‘’]?(?:\s+(?:range|vung|[A-Z]{1,3}\d+)|$)/i);
  return match ? cleanName(match[1]) : '';
}

function parseSheetName(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'doc sheet',
    'xem sheet',
    'read sheet',
    'doc bang tinh',
    'xem bang tinh',
    'noi dung sheet',
    'noi dung bang tinh'
  ];

  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (bodyNormalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }

    if (bodyNormalized === prefix) {
      return '';
    }
  }

  const range = parseRange(bodyOriginal);
  if (range) {
    bodyOriginal = bodyOriginal.replace(new RegExp(range, 'i'), ' ').trim();
  }

  const tab = parseSheetTab(bodyOriginal);
  if (tab) {
    bodyOriginal = bodyOriginal
      .replace(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?[^"'“”‘’]+?["'“”‘’]?(?:\s+(?:range|vung)|$)/i, ' ')
      .trim();
  }

  bodyOriginal = bodyOriginal
    .replace(/\brange\b/gi, ' ')
    .replace(/\bvung\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return cleanName(bodyOriginal);
}

const spreadsheetId =
  source.spreadsheetId ||
  source.sheetId ||
  source.fileId ||
  source.targetId ||
  args.spreadsheetId ||
  args.sheetId ||
  args.fileId ||
  args.targetId ||
  payload.spreadsheetId ||
  payload.sheetId ||
  payload.fileId ||
  payload.targetId ||
  '';

const range =
  source.range ||
  source.rangeName ||
  args.range ||
  args.rangeName ||
  payload.range ||
  payload.rangeName ||
  parseRange(raw) ||
  'A1:Z30';

const sheetTab =
  source.sheetTab ||
  args.sheetTab ||
  payload.sheetTab ||
  parseSheetTab(raw) ||
  '';

const sheetName = cleanName(
  source.sheetName ||
  source.targetName ||
  source.title ||
  source.query ||
  args.sheetName ||
  args.targetName ||
  args.title ||
  args.query ||
  payload.sheetName ||
  payload.targetName ||
  payload.title ||
  payload.query ||
  parseSheetName(raw)
);

const hasTarget = Boolean(spreadsheetId || sheetName);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    spreadsheetId,
    sheetId: spreadsheetId,
    fileId: source.fileId || args.fileId || payload.fileId || spreadsheetId,
    targetId: spreadsheetId,
    sheetName,
    targetName: cleanName(source.targetName || args.targetName || payload.targetName || sheetName),
    fileName: cleanName(source.fileName || args.fileName || payload.fileName || sheetName),
    title: cleanName(source.title || args.title || payload.title || sheetName),
    query: cleanName(source.query || args.query || payload.query || sheetName),
    range,
    rangeName: cleanName(source.rangeName || args.rangeName || payload.rangeName || range),
    sheetTab,

    hasTarget,
    response: hasTarget
      ? ''
      : '📊 <b>Đọc Google Sheet</b>\n\nVí dụ:\n<code>đọc sheet Chi tiêu</code>\n<code>đọc sheet Chi tiêu A1:C10</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      found: false,
      spreadsheetId: '',
      sheetId: '',
      targetId: '',
      response: 'Không tìm thấy bảng tính phù hợp với: <b>' + escapeHtml(source.sheetName || source.targetName || source.query || '') + '</b>'
    }
  }];
}

const sheet = rows[0];

return [{
  json: {
    ...source,
    ...sheet,

    found: true,
    spreadsheetId: sheet.id || source.spreadsheetId || '',
    sheetId: sheet.id || source.sheetId || '',
    fileId: sheet.id || source.fileId || '',
    targetId: sheet.id || source.targetId || source.spreadsheetId || '',
    sheetName: sheet.name || source.sheetName || source.targetName || source.query || '',
    targetName: source.targetName || sheet.name || source.sheetName || source.query || '',
    fileName: source.fileName || sheet.name || source.sheetName || source.query || '',
    title: source.title || sheet.name || source.sheetName || source.query || '',
    query: source.query || source.sheetName || source.targetName || '',
    webViewLink: sheet.webViewLink || source.webViewLink || '',
    mimeType: sheet.mimeType || source.mimeType || '',
    range: source.range || 'A1:Z30',
    rangeName: source.rangeName || source.range || 'A1:Z30',
    sheetTab: source.sheetTab || '',
    chatId: source.chatId || ''
  }
}];

function getJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

const source = {
  ...getJson('Prepare Action'),
  ...getJson('Resolve Search Result')
};
const result = $input.item.json || {};
const rows = Array.isArray(result.values) ? result.values : [];
const limited = rows.slice(0, 10);
let preview = limited.map((row, index) => `${index + 1}. ${row.map((cell) => String(cell)).join(' | ')}`).join('\n');
let truncated = rows.length > 10;
if (preview.length > 1000) {
  preview = preview.slice(0, 1000).trimEnd();
  truncated = true;
}

const sheetId = source.spreadsheetId || source.sheetId || '';
const title = source.sheetName || source.name || 'Không rõ tên';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');
const shownRange = source.sheetTab ? `'${source.sheetTab}'!${source.range || 'A1:Z30'}` : (source.range || 'A1:Z30');

let text = `Mia đọc được Google Sheet "${title}" ở range ${shownRange}.`;
if (link) text += `\nLink: ${link}`;
text += `\n\nDữ liệu xem trước:\n${preview || '(Range này chưa có dữ liệu.)'}`;
if (truncated) text += '\n\nMia đã rút gọn bảng để Telegram dễ đọc hơn.';

return [{
  json: {
    ok: true,
    tool: 'sheets.read_sheet',
    chatId: source.chatId || result.chatId || '',
    text: text.trim(),
    links: link ? [link] : [],
    result: { spreadsheetId: sheetId, title, range: shownRange, rows: limited },
    meta: { truncated, rowCount: rows.length }
  }
}];

const source = $json || {};
const tool = source.tool || source.workflowKey || '';
const target =
  source.docName ||
  source.sheetName ||
  source.query ||
  source.fileName ||
  source.rawText ||
  source.text ||
  '';

let text = source.response || source.text || '';
if (!text) {
  text = target
    ? `Mia chưa tìm thấy tài liệu phù hợp với "${target}".`
    : 'Mia cần tên tài liệu hoặc bảng tính để đọc.';
}

return [{
  json: {
    ok: false,
    tool,
    chatId: source.chatId || '',
    text: String(text).trim(),
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false ? 'missing_target' : 'not_found'
    }
  }
}];
